css:
.compare {
  display: flex;
  gap: 16px;
  padding: 12px;
}

.box {
  width: 160px;
  padding: 20px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

.plain {
  box-sizing: content-box; /* width is the content only */
}

.tight {
  box-sizing: border-box; /* width includes padding */
}
